/* ---------- Audio deck ---------- */
(function deck() {
  var root = document.getElementById('deck');
  if (!root || !window.DECK_SHOWS) return;
  var shows = window.DECK_SHOWS;
  var $ = function (id) { return document.getElementById(id); };
  var el = { cart: $('d-cartlabel'), lcd: $('d-lcd'), meta: $('d-meta'), title: $('d-title'), show: $('d-show'), cur: $('d-cur'), tot: $('d-tot'),
             scrub: $('d-scrub'), prev: $('d-prev'), play: $('d-play'), next: $('d-next'), vol: $('d-vol'), list: $('d-list'), carts: $('d-carts'), vl: $('d-vl'), vr: $('d-vr') };
  var audio = new Audio();
  audio.preload = 'none';
  var showI = 0, trackI = 0, flat = [], playing = false, dragging = false;

  function two(n) { return (n < 10 ? '0' : '') + n; }
  function fmt(sec) { sec = Math.max(0, Math.floor(sec || 0)); return two(Math.floor(sec / 60)) + ':' + two(sec % 60); }
  function safe(x) { return String(x).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function trackUrl(show, f) { return 'https://archive.org/download/' + show.id + '/' + encodeURIComponent(f); }
  function dur() { return isFinite(audio.duration) && audio.duration > 0 ? audio.duration : (flat[trackI] ? flat[trackI].d : 0); }
  function setP(input, frac) { input.style.setProperty('--p', Math.max(0, Math.min(1, frac)) * 100 + '%'); }

  /* meters: 12 segments each */
  var SEG = 12;
  [el.vl, el.vr].forEach(function (m) { for (var i = 0; i < SEG; i++) { var b = document.createElement('i'); if (i >= SEG - 3) b.className = 'hot'; m.appendChild(b); } });
  var levels = [0, 0], targets = [0, 0], raf = 0, tick = 0;
  function paintMeters() {
    [el.vl, el.vr].forEach(function (m, k) {
      var on = Math.round(levels[k] * SEG);
      for (var i = 0; i < SEG; i++) m.children[i].classList.toggle('on', i < on);
    });
  }
  function meterFrame() {
    tick++;
    if (playing) {
      if (tick % 5 === 0) {
        var beat = 0.5 + 0.5 * Math.sin(audio.currentTime * 7.3);
        targets[0] = Math.min(1, 0.32 + 0.3 * Math.random() + 0.22 * beat);
        targets[1] = Math.min(1, 0.32 + 0.3 * Math.random() + 0.22 * (1 - beat) + 0.06);
      }
    } else { targets[0] = targets[1] = 0; }
    var moving = false;
    for (var k = 0; k < 2; k++) {
      var d = targets[k] - levels[k];
      levels[k] += d * (d > 0 ? 0.35 : 0.12);
      if (Math.abs(d) > 0.01) moving = true;
    }
    paintMeters();
    raf = (playing || moving) ? requestAnimationFrame(meterFrame) : 0;
  }
  function kickMeters() { if (!raf) raf = requestAnimationFrame(meterFrame); }

  /* rendering */
  function flatten(show) {
    var out = [];
    show.sets.forEach(function (s) { s.tracks.forEach(function (t) { out.push({ t: t.t, f: t.f, d: t.d, set: s.n }); }); });
    return out;
  }
  function renderCarts() {
    shows.forEach(function (s, k) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'cart'; b.setAttribute('aria-pressed', k === showI ? 'true' : 'false'); b.setAttribute('data-k', k);
      b.innerHTML = '<b>' + safe(s.label) + '</b><span>' + safe(s.venue) + '</span><small>' + safe(s.city) + '</small>';
      el.carts.insertBefore(b, el.carts.querySelector('a'));
    });
  }
  function renderList() {
    var html = '', last = '', n = 0;
    flat.forEach(function (t, i) {
      if (t.set !== last) { html += '<li class="set-h">' + safe(t.set) + '</li>'; last = t.set; }
      n++;
      html += '<li><button class="trk" type="button" data-i="' + i + '"><span class="n"><span class="num">' + two(n) + '</span><span class="eq" aria-hidden="true"><i></i><i></i><i></i></span></span><span class="t">' + safe(t.t) + '</span><span class="d">' + fmt(t.d) + '</span></button></li>';
    });
    el.list.innerHTML = html;
  }
  function markActive(scroll) {
    var rows = el.list.querySelectorAll('.trk');
    rows.forEach(function (r) { if (+r.getAttribute('data-i') === trackI) r.setAttribute('aria-current', 'true'); else r.removeAttribute('aria-current'); });
    if (scroll) {
      var r = el.list.querySelector('.trk[aria-current="true"]');
      if (r) { var li = r.parentNode; el.list.scrollTop = Math.max(0, li.offsetTop - el.list.clientHeight / 2 + li.offsetHeight / 2); }
    }
  }
  function setPlaying(on) {
    playing = on;
    root.classList.toggle('playing', on);
    el.play.classList.toggle('on', on);
    el.play.setAttribute('aria-label', on ? 'Pause' : 'Play');
    el.play.innerHTML = (on ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 5h4v14H6zM14 5h4v14h-4z"/></svg><span>Pause</span>' : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg><span>Play</span>');
    if ('mediaSession' in navigator) navigator.mediaSession.playbackState = on ? 'playing' : 'paused';
    kickMeters();
  }
  function showMeta() {
    var s = shows[showI], t = flat[trackI];
    el.meta.textContent = t.set + ' · Song ' + (trackI + 1) + ' of ' + flat.length;
    el.title.textContent = t.t;
    el.show.textContent = s.venue + ' · ' + s.label;
    el.cart.textContent = s.date;
    el.lcd.classList.remove('err');
  }
  function load(i, play, scroll) {
    trackI = i;
    var s = shows[showI], t = flat[i];
    audio.src = trackUrl(s, t.f);
    showMeta();
    el.cur.textContent = '00:00'; el.tot.textContent = fmt(t.d); el.scrub.value = 0; setP(el.scrub, 0);
    markActive(scroll);
    if ('mediaSession' in navigator && window.MediaMetadata) {
      navigator.mediaSession.metadata = new MediaMetadata({ title: t.t, artist: 'The Bedlam Brothers', album: s.venue + ' · ' + s.label });
    }
    if (play) start();
  }
  function start() {
    var p = audio.play();
    if (p && p.catch) p.catch(function () { setPlaying(false); });
  }
  function step(dir, auto) {
    var i = trackI + dir;
    if (i < 0) { audio.currentTime = 0; return; }
    if (i >= flat.length) { audio.pause(); setPlaying(false); load(0, false, true); return; }
    load(i, playing || auto, true);
  }
  function chooseShow(k) {
    if (k === showI) return;
    audio.pause(); setPlaying(false);
    showI = k; flat = flatten(shows[k]);
    el.carts.querySelectorAll('.cart').forEach(function (b) { b.setAttribute('aria-pressed', +b.getAttribute('data-k') === k ? 'true' : 'false'); });
    renderList(); el.list.scrollTop = 0; load(0, false, false);
  }

  /* wiring */
  audio.addEventListener('play', function () { setPlaying(true); });
  audio.addEventListener('pause', function () { setPlaying(false); });
  audio.addEventListener('ended', function () { step(1, true); });
  audio.addEventListener('waiting', function () { el.meta.textContent = 'Loading…'; });
  audio.addEventListener('playing', function () { showMeta(); });
  audio.addEventListener('loadedmetadata', function () { el.tot.textContent = fmt(dur()); });
  audio.addEventListener('timeupdate', function () {
    if (dragging) return;
    var d = dur();
    el.cur.textContent = fmt(audio.currentTime);
    var f = d ? audio.currentTime / d : 0;
    el.scrub.value = Math.round(f * 1000); setP(el.scrub, f);
  });
  audio.addEventListener('error', function () {
    setPlaying(false);
    el.lcd.classList.add('err');
    el.meta.textContent = 'Playback problem';
    el.title.textContent = 'Can’t load this song';
    el.show.textContent = 'Check your connection or pick another';
  });
  el.play.addEventListener('click', function () { if (playing) audio.pause(); else start(); });
  el.prev.addEventListener('click', function () { if (audio.currentTime > 3) audio.currentTime = 0; else step(-1, false); });
  el.next.addEventListener('click', function () { step(1, false); });
  el.scrub.addEventListener('input', function () {
    dragging = true;
    var f = el.scrub.value / 1000; setP(el.scrub, f); el.cur.textContent = fmt(f * dur());
  });
  el.scrub.addEventListener('change', function () {
    var d = dur(); if (d) audio.currentTime = el.scrub.value / 1000 * d;
    dragging = false;
  });
  el.vol.addEventListener('input', function () { audio.volume = el.vol.value / 100; setP(el.vol, el.vol.value / 100); });
  audio.volume = el.vol.value / 100; setP(el.vol, el.vol.value / 100);
  el.list.addEventListener('click', function (e) {
    var b = e.target.closest('.trk'); if (!b) return;
    var i = +b.getAttribute('data-i');
    if (i === trackI && playing) { audio.pause(); return; }
    if (i === trackI) { start(); return; }
    load(i, true, false);
  });
  el.carts.addEventListener('click', function (e) { var b = e.target.closest('.cart'); if (b) chooseShow(+b.getAttribute('data-k')); });
  if ('mediaSession' in navigator) {
    var ms = navigator.mediaSession;
    try {
      ms.setActionHandler('play', function () { start(); });
      ms.setActionHandler('pause', function () { audio.pause(); });
      ms.setActionHandler('previoustrack', function () { step(-1, false); });
      ms.setActionHandler('nexttrack', function () { step(1, false); });
    } catch (err) { /* some browsers lack these actions */ }
  }

  flat = flatten(shows[showI]);
  renderCarts(); renderList(); load(0, false, false);
  paintMeters();
})();
